<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {mutate,PLANNING_PREVIEW_TIMEOUT_MS} from '../api'
import {isMultiDayItinerary,explorationApi,type EnginePreview,type PlanningObjective} from '../explorationApi'
import {clone,clock,journey,loadJourney,loadConfirmedRoute,localDate,notify} from '../journey'
import {memoryEpoch} from '../voiceDraft'
import PlanPreview from './PlanPreview.vue'
interface Day{day_id:string;business_date:string;starts_at:string;ends_at:string;pace?:string;objective?:PlanningObjective;modes?:string[]}
const open=ref(false),busy=ref(false),error=ref(''),days=ref<Day[]>([]),preview=ref<EnginePreview>(),selected=ref(0)
let generation=0,disposed=false
const eligible=computed(()=>{const p=journey.route?.itinerary;return !!journey.trip&&['ACTIVE','PAUSED'].includes(journey.trip.status)&&!!p&&isMultiDayItinerary(p)&&p.days.some(d=>d.business_date===localDate()&&d.status!=='closed')})
function reset(){generation++;open.value=false;busy.value=false;error.value='';days.value=[];preview.value=undefined}
watch(()=>[journey.trip?.id,journey.trip?.version,journey.route?.version,journey.focusedDayId,memoryEpoch.value],reset)
onBeforeUnmount(()=>{disposed=true;generation++})
function edit(){reset();const p=journey.route?.itinerary;if(!p||!isMultiDayItinerary(p))return;days.value=clone((journey.route!.requirements?.days as Day[]||[]).filter(d=>d.business_date>=localDate()&&p.days.some(a=>a.day_id===d.day_id&&a.status!=='closed')));for(const d of days.value){const source=p.days.find(a=>a.day_id===d.day_id)!.requirements;d.pace=d.pace||source.pace;d.objective=d.objective||source.objective;d.modes=d.modes||clone(source.modes)}open.value=true}
function dirty(){generation++;preview.value=undefined;error.value=''}
function time(d:Day,key:'starts_at'|'ends_at',value:string){d[key]=d.business_date+'T'+value+':00+08:00';dirty()}
async function calculate(){if(busy.value||!journey.trip||!journey.route?.requirements)return;dirty();const token=generation,id=journey.trip.id;busy.value=true;try{const req=clone(journey.route.requirements);req.days=(req.days as Day[]).map(d=>days.value.find(a=>a.day_id===d.day_id)||d);const result=await mutate<EnginePreview>(`/city/v1/trips/${id}/engine/replan-preview`,{expected_version:journey.trip.version,requirements:req,scope:'current_and_future'},'POST',PLANNING_PREVIEW_TIMEOUT_MS);if(disposed||generation!==token)return;if(!result.candidate_id)throw new Error(result.result?.issues?.map(i=>i.message).join('；')||'当前条件没有完整可确认方案');preview.value=result;selected.value=0}catch(e){if(!disposed&&generation===token)error.value=(e as Error).message}finally{if(!disposed&&generation===token)busy.value=false}}
async function confirm(){if(busy.value||!preview.value||!journey.trip)return;const token=generation,id=journey.trip.id,p=preview.value;busy.value=true;try{await explorationApi.confirm(id,p.base_version,p.candidate_id!,selected.value);if(disposed||generation!==token)return;reset();await loadJourney(true);await loadConfirmedRoute();notify('已更新今天剩余及后续天')}catch(e){if(!disposed&&generation===token)error.value=(e as Error).message}finally{if(!disposed&&generation===token)busy.value=false}}
</script>
<template><section v-if="eligible" class="suffix-planning" aria-label="连续多日调整"><button v-if="!open" type="button" class="button secondary" @click="edit">调整今天及后续天</button><template v-else><h3>调整今天剩余及后续天</h3><p>今天从已确认的位置继续；已完成记录、固定活动及酒店衔接保留。日期条件允许的目标会在剩余日期内重新安排。</p><form @submit.prevent="calculate"><fieldset :disabled="busy" @input="dirty" @change="dirty"><details v-for="d in days" :key="d.day_id" open><summary>{{d.business_date}}{{d.business_date===localDate()?' · 今天剩余':''}}</summary><div class="suffix-fields"><label v-if="d.business_date>localDate()">开始时间<input type="time" :value="clock(d.starts_at)" required @input="time(d,'starts_at',($event.target as HTMLInputElement).value)"></label><label>结束时间<input type="time" :value="clock(d.ends_at)" required @input="time(d,'ends_at',($event.target as HTMLInputElement).value)"></label><label>游玩节奏<select v-model="d.pace"><option value="relaxed">轻松</option><option value="standard">适中</option><option value="compact">紧凑</option></select></label><label>安排偏好<select v-model="d.objective"><option value="balanced">均衡</option><option value="less_walking">少走路</option><option value="less_waiting">少等待</option><option value="lower_cost">省钱</option></select></label></div><label v-for="m in [{id:'walking',name:'步行'},{id:'transit',name:'公交'},{id:'driving',name:'打车 / 自驾'}]" :key="m.id" class="suffix-mode"><input v-model="d.modes" type="checkbox" :value="m.id">{{m.name}}</label></details><button type="submit" class="button primary">预览今天及后续天</button></fieldset></form><p v-if="busy" role="status">正在处理…</p><p v-if="error" role="alert">{{error}}</p><RouterLink v-if="error&&journey.trip" :to="'/city-trip/manage/'+journey.trip.id">核对今天的当前位置</RouterLink><template v-if="preview"><PlanPreview :plans="preview.result.itineraries" :selected="selected" :disabled="busy" :changes="preview.alternative_changes?.[selected]" @select="selected=$event"/><button type="button" class="button primary" :disabled="busy" @click="confirm">确认更新今天及后续天</button></template><button type="button" :disabled="busy" @click="reset">保留原安排</button></template></section></template>
<style scoped>.suffix-planning{margin:16px 0;padding:14px;border:1px solid #ded4c2;border-radius:10px;font-size:13px;line-height:1.8}.suffix-planning fieldset{border:0;padding:0;display:grid;gap:12px}.suffix-fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.suffix-planning summary{min-height:44px;cursor:pointer}.suffix-planning select,.suffix-planning input:not([type=checkbox]){display:block;width:100%;min-height:44px;box-sizing:border-box}.suffix-planning button{min-height:44px;padding:8px}.suffix-mode{display:inline-flex;margin:10px 10px 10px 0}</style>
